public static int applyLuminosity(int packedLight, int luminosity) {
    // if full bright, skip some math
    if (luminosity >= 15) {
      return TintedArmorTexture.MAX_LIGHT;
    }
    // inlined version of methods from LightTexture
    return Math.max(luminosity, (packedLight & 0xFFFF) >> 4) << 4
      | Math.max(luminosity, packedLight >> 20 & 0xFFFF) << 20;
  }

@Override
  public ArmorTexture getArmorTexture(ItemStack stack, TextureType type, RegistryAccess access) {
    CompoundTag tag = stack.getTag();
    if (tag != null && tag.contains(ToolStack.TAG_MATERIALS, Tag.TAG_LIST)) {
      String material = tag.getList(ToolStack.TAG_MATERIALS, Tag.TAG_STRING).getString(index);
      if (!material.isEmpty() && cache.computeIfAbsent(material, this)) {
        return apply.getArmorTexture(stack, type, access);
      }
    }
    return ArmorTexture.EMPTY;
  }

@Override
  public Boolean apply(String string) {
    MaterialVariantId material = MaterialVariantId.tryParse(string);
    if (material != null) {
      return MaterialRenderInfoLoader.INSTANCE.hasFallback(material, fallback);
    }
    return false;
  }

@Override
protected void renderModelPart(PoseStack poseStack, MultiBufferSource bufferSource, ItemStack stack, LivingEntity entity, EquipmentSlot slot, int light, int dyeColor, HumanoidModel<LivingEntity> contextModel, ArcanistRobesModel<LivingEntity> armorModel) {
	if(stack.getItem() instanceof ArcanistRobesItem wizardArmor) {
		int hexColor = wizardArmor.getColor(stack);

		if(stack.has(DataComponents.CUSTOM_NAME) && stack.getHoverName().getString().equals("jeb_")) {
			int interval = 15;
			int idfk = entity.tickCount / interval + entity.getId();
			int colorCount = DyeColor.values().length;
			float f = ((entity.tickCount % interval) + Minecraft.getInstance().getFrameTimeNs()) / 15f;
			int color1 = Sheep.getColor(DyeColor.byId(idfk % colorCount));
			int color2 = Sheep.getColor(DyeColor.byId((idfk + 1) % colorCount));
			hexColor = FastColor.ARGB32.lerp(f, color1, color2);
		}

		model.renderToBuffer(poseStack, ItemRenderer.getArmorFoilBuffer(bufferSource, RenderType.armorCutoutNoCull(mainTexture), false), light, OverlayTexture.NO_OVERLAY, hexColor);
		model.renderToBuffer(poseStack, ItemRenderer.getArmorFoilBuffer(bufferSource, RenderType.armorCutoutNoCull(overlayTexture), false), light, OverlayTexture.NO_OVERLAY, 0xffffffff);
	}
}

@Override
public @NotNull Model getGenericArmorModel(@NotNull LivingEntity entity, @NotNull ItemStack itemStack, @NotNull EquipmentSlot armorSlot, @NotNull HumanoidModel playerModel) {
    var model = super.getGenericArmorModel(entity, itemStack, armorSlot, playerModel);
    if (armorSlot.equals(EquipmentSlot.CHEST)) {
        var skin = itemStack.get(MalumDataComponents.APPLIED_ITEM_SKIN);
        RenderTypeToken scarfToken = skin != null ?
                RenderTypeToken.createToken(skin.name().withPrefix("textures/vfx/scarf/").withSuffix(".png"))
                : MalumRenderTypeTokens.SCARF;
        ScarfRenderHandler.addScarfRenderer(entity, (consumer) -> {
            boolean noSkin = skin == null;
            int scarfCount = noSkin ? 2 : 1;
            float scale = noSkin ? 0.35f : 0.4f;
            float endingScale = noSkin ? 0.45f : 1f;
            float offset = noSkin ? 0.25f : 0.2f;
            for (int i = 0; i < scarfCount; i++) {
                var data = new ScarfRenderHandler.ScarfRenderData(scarfToken, ClientConfig.SCARF_LENGTH.getConfigValue())
                        .setPredicate(() -> {
                            ItemStack stack = entity.getItemBySlot(armorSlot);
                            return !stack.isEmpty() && stack.is(itemStack.getItem());
                        })
                        .setScale(scale)
                        .setEndingScale(endingScale)
                        .setHorizontalOffset(i == 0 ? -offset : offset);
                if (noSkin) {
                    data.setSecondaryColor(new Color(150, 150, 150));
                }
                consumer.accept(data);
            }
        });
    }
    return model;
}
